{"file_path":"src/merge.js","content":"function changes(base, side, who) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const res = []
  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n
  j = m
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const out = []
  let conflict = false
  const emit = (kind, lines) => out.push({ kind, lines })
  let pos = 0
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) emit('stable', base.slice(pos, rs))
    pos = re
    const baseLines = base.slice(rs, re)
    if (group.length === 1) {
      const c = group[0]
      emit(c.who === 0 ? 'mine' : 'theirs', (c.who === 0 ? mine : theirs).slice(c.ss, c.se))
      continue
    }
    const repl = who => {
      const cs = group.filter(c => c.who === who)
      const src = who === 0 ? mine : theirs
      if (!cs.length) return baseLines
      const ms = Math.min(...cs.map(c => c.bs))
      const me = Math.max(...cs.map(c => c.be))
      const s = cs[0].ss - (ms - rs)
      const e = cs[cs.length - 1].se + (re - me)
      return src.slice(s, e)
    }
    const a = repl(0)
    const b = repl(1)
    if (eq(a, b)) emit('both', a)
    else if (eq(a, baseLines)) emit('theirs', b)
    else if (eq(b, baseLines)) emit('mine', a)
    else {
      conflict = true
      out.push({ kind: 'conflict', a, o: baseLines, b })
    }
  }
  if (pos < base.length) emit('stable', base.slice(pos))
  const lines = []
  for (const r of out) {
    if (mode === 'regions') {
      if (r.kind === 'conflict') lines.push(`conflict mine=${r.a.length} base=${r.o.length} theirs=${r.b.length}`)
      else lines.push(`${r.kind} ${r.lines.length}`)
    } else if (r.kind === 'conflict') {
      lines.push('<<<<<<< mine', ...r.a)
      if (mode === 'merge') lines.push('||||||| base', ...r.o)
      lines.push('=======', ...r.b, '>>>>>>> theirs')
    } else lines.push(...r.lines)
  }
  return { out: lines, conflict }
}
"}

