/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parse, count } from './election.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  fail('error: usage: cli.js rounds|tally')
}

const text = readFileSync(0, 'utf8')
let election
try {
  election = parse(text)
} catch (e) {
  if (e && e.isElectionError) fail(e.message)
  throw e
}
