{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261104T225220Z/cell-1UIg1O/src/election.js","content":"function err(msg) {
  const e = new Error(msg)
  e.isElectionError = true
  return e
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let seen = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const tok = line.split(/\s+/)
    const word = tok[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (tok.length < 2) throw err(`error: line ${n}: expected candidates <name>...`)
      candidates = []
      seen = new Set()
      for (const name of tok.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) throw err(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
        candidates.push(name)
      }
    } else if (word === 'ballot') {
      if (candidates === null) throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (tok.length < 3) throw err(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(tok[1])) throw err(`error: line ${n}: count must be a positive integer`)
      const names = tok.slice(2)
      const used = new Set()
      for (const name of names) {
        if (!seen.has(name)) throw err(`error: line ${n}: unknown candidate ${name}`)
        if (used.has(name)) throw err(`error: line ${n}: candidate ${name} is repeated`)
        used.add(name)
      }
      ballots.push({ count: BigInt(tok[1]), names })
    } else {
      throw err(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw err('error: no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }, mode) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const out = []
  let rounds = 0
  let result
  for (;;) {
    rounds++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.names.find((x) => continuing.has(x))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const listed = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    let line = `round ${rounds}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
    out.push(line)
    if (active === 0n) {
      result = 'no winner'
      break
    }
    const win = listed.find(([, v]) => v * 2n > active)
    if (win) {
      result = `winner ${win[0]}`
      break
    }
    let min = listed[listed.length - 1][1]
    let tied = listed.filter(([, v]) => v === min).map(([c]) => c)
    while (tied.length > 1) {
      let narrowed = false
      for (let r = 0; r < rounds; r++) {
        const vs = tied.map((c) => history.get(c)[r])
        const lo = vs.reduce((a, b) => (b < a ? b : a))
        if (vs.some((v) => v !== lo)) {
          tied = tied.filter((c) => history.get(c)[r] === lo)
          narrowed = true
          break
        }
      }
      if (!narrowed) break
    }
    tied.sort()
    const gone = tied[tied.length - 1]
    continuing.delete(gone)
    out.push(`eliminated ${gone}`)
  }
  if (mode === 'tally') return `rounds ${rounds}\n${result}\n`
  return out.join('\n') + '\n' + result + '\n'
}
"}

