{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  // Advance one code point, tracking position.
  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // Consume a run of digits (underscore allowed between two digits of the run).
  const run = (ok) => {
    if (!ok(s[i])) return false
    adv()
    for (;;) {
      if (ok(s[i])) adv()
      else if (s[i] === '_' && ok(s[i + 1])) { adv(); adv() }
      else break
    }
    return true
  }

  while (i < n) {
    const c = s[i]
    const sl = line
    const sc = col
    const start = i

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }

    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }

    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      const begin = i
      while (i < n && s[i] !== '"') adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      const value = s.slice(begin, i).join('')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', value })
      continue
    }

    if (isIdStart(c)) {
      while (i < n && isIdPart(s[i])) adv()
      const value = s.slice(start, i).join('')
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(value) ? 'keyword' : 'ident', value })
      continue
    }

    if (isDigit(c)) {
      let ok = true
      const p = (s[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        adv(); adv()
        ok = run(p === 'x' ? isHex : p === 'b' ? isBin : isOct)
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { adv(); run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1])) { adv(); run(isDigit) }
          else if ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2])) { adv(); adv(); run(isDigit) }
        }
      }
      if (!ok || isIdPart(s[i])) {
        while (i < n && isIdPart(s[i])) adv()
        throw new ScanError(sl, sc, `invalid number ${s.slice(start, i).join('')}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', value: s.slice(start, i).join('') })
      continue
    }

    if (c === '"') {
      adv()
      let value = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '"') { adv(); break }
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch !== '\\') { value += adv(); continue }
        const bl = line
        const bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) { adv(); value += simple[e] }
        else if (e === 'x') {
          if (!isHex(s[i + 1]) || !isHex(s[i + 2])) throw bad()
          adv()
          value += String.fromCodePoint(parseInt(s[i] + s[i + 1], 16))
          adv(); adv()
        } else if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2
          let h = ''
          while (isHex(s[j])) h += s[j++]
          if (h === '' || s[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw bad()
          while (i <= j) adv()
          value += String.fromCodePoint(parseInt(h, 16))
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', value })
      continue
    }

    const two = c + (s[i + 1] ?? '')
    const p = PUNCT.find((x) => (x.length === 2 ? x === two : x === c))
    if (p) {
      for (let k = 0; k < p.length; k++) adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', value: p })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
"}

