const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'e', v: code })
const num = (n) => ({ t: 'n', v: n })
const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
