  return s.length === 1 ? s.charCodeAt(0) - 64 : (s.charCodeAt(0) - 64) * 26 + s.charCodeAt(1) - 64
}
function parseAddr(word) {
  const m = ADDR.exec(word.toUpperCase())
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { name: m[1] + row, col: colIndex(m[1]), row, colName: m[1] }
