  function cmp() {
    let l = add()
    while (peek() && peek().k === 'op' && CMP.includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (isOp('(')) { p++; const e = cmp(); expect(')'); return e }
    if (t.k !== 'word') throw new Bad()
