  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const word = m[1]
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word.toUpperCase()}`)
  if (cells.has(a.name)) fail(`error: line ${i + 1}: cell ${a.name} is declared twice`)
  cells.set(a.name, { addr: a, content: m[2] })
})

// ---------- formula parsing ----------
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0].toUpperCase() }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

class Bad extends Error {}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new Bad(); p++ }
  const CMP = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (peek() && peek().k === 'op' && CMP.includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (isOp('(')) { p++; const e = cmp(); expect(')'); return e }
    if (t.k !== 'word') throw new Bad()
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        args.push(cmp())
        while (isOp(',')) { p++; args.push(cmp()) }
      }
      expect(')')
      return { n: 'call', name: t.v, args }
    }
    if (isOp(':')) {
      p++
      const t2 = toks[p]
      if (!t2 || t2.k !== 'word') throw new Bad()
      p++
      return { n: 'range', a: t.v, b: t2.v }
    }
    if (t.v === 'TRUE') return { n: 'bool', v: true }
    if (t.v === 'FALSE') return { n: 'bool', v: false }
    return { n: 'ref', w: t.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e instanceof Bad) return null
    throw e
  }
}

function misplaced(e, direct = false) {
  switch (e.n) {
    case 'range': return !direct
    case 'bin': return misplaced(e.l) || misplaced(e.r)
    case 'un': return misplaced(e.e)
    case 'call': return e.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(a, b) {
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(mk(c, r))
  return out
}

function collectAddrs(e, out) {
  switch (e.n) {
    case 'ref': { const a = parseAddr(e.w); if (a) out.push(a); break }
    case 'range': {
      const a = parseAddr(e.a), b = parseAddr(e.b)
      if (a && b) out.push(...rangeCells(a, b))
      else {
        if (a) out.push(a)
        if (b) out.push(b)
      }
      break
    }
    case 'bin': collectAddrs(e.l, out); collectAddrs(e.r, out); break
    case 'un': collectAddrs(e.e, out); break
    case 'call': e.args.forEach((a) => collectAddrs(a, out)); break
  }
}

// ---------- evaluation ----------
const memo = new Map()
const active = new Set()

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return err(content)
  return { t: 's', v: content }
}

function cellValue(name) {
  if (memo.has(name)) return memo.get(name)
  const c = cells.get(name)
  if (!c) return num(0)
  if (active.has(name)) return err('#CYCLE!')
  active.add(name)
  let v
  if (c.content[0] === '=') {
    const tree = parseFormula(c.content.slice(1))
    v = !tree || misplaced(tree) ? err('#ERR!') : evaluate(tree)
  } else v = literal(c.content)
  active.delete(name)
  memo.set(name, v)
  return v
}

function toNum(v) {
  if (v.t === 'e' || v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (n) => (Number.isFinite(n) ? num(n) : err('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }

function cpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

function rangeValues(e) {
  const a = parseAddr(e.a), b = parseAddr(e.b)
  if (!a || !b) return [err('#REF!')]
  return rangeCells(a, b).map((c) => cellValue(c.name))
}

function evaluate(e) {
  switch (e.n) {
    case 'num': return num(e.v)
    case 'bool': return { t: 'b', v: e.v }
    case 'ref': {
      const a = parseAddr(e.w)
      return a ? cellValue(a.name) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = toNum(evaluate(e.e))
      if (x.t === 'e') return x
      return e.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = evaluate(e.l)
      if (['=', '<>', '<', '<=', '>', '>='].includes(e.op)) {
        if (l.t === 'e') return l
        const r = evaluate(e.r)
        if (r.t === 'e') return r
        let d
        if (l.t !== r.t) d = rank[l.t] - rank[r.t]
        else if (l.t === 's') d = cpStr(l.v, r.v)
        else d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[e.op]
        return { t: 'b', v: res }
      }
      const x = toNum(l)
      if (x.t === 'e') return x
      const y = toNum(evaluate(e.r))
      if (y.t === 'e') return y
      switch (e.op) {
        case '+': return finite(x.v + y.v)
        case '-': return finite(x.v - y.v)
        case '*': return finite(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : finite(x.v / y.v)
        case '^': return finite(Math.pow(x.v, y.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(e)
  }
  return err('#ERR!')
}

function call(e) {
  const name = e.name
  const n = e.args.length
  const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (!multi.includes(name) && name !== 'ABS' && name !== 'IF') return err('#NAME?')
  if (name === 'IF') {
    if (n !== 3) return err('#ERR!')
    const c = evaluate(e.args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evaluate(e.args[truth ? 1 : 2])
  }
  if (n < 1 || (name === 'ABS' && n !== 1)) return err('#ERR!')
  const vals = []
  for (const a of e.args) {
    if (a.n === 'range') vals.push(...rangeValues(a))
    else vals.push(evaluate(a))
  }
  const firstErr = vals.find((v) => v.t === 'e')
  if (firstErr) return firstErr
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS': return nums.length === 1 ? num(Math.abs(nums[0])) : err('#ERR!')
    case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

// ---------- output ----------
function show(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
const out = []
for (const c of sorted) {
  const name = c.addr.name
  if (mode === 'values') out.push(`${name}=${show(cellValue(name))}`)
  else {
    let names = []
    if (c.content[0] === '=') {
      const tree = parseFormula(c.content.slice(1))
      if (tree) {
        const as = []
        collectAddrs(tree, as)
        const seen = new Map()
        for (const a of as) seen.set(a.name, a)
        names = [...seen.values()].sort((a, b) => a.col - b.col || a.row - b.row).map((a) => a.name)
      }
    }
    out.push(`${name}:` + names.map((x) => ' ' + x).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

