import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdCont = (c) => isLetter(c) || isDigit(c) || c === '_'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col, start = i
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      while (i < n) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2); if (depth === 0) break }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let body = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        body += d
      }
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(body) })
      continue
    }
    if (isLetter(c) || c === '_') {
      while (isIdCont(cs[i])) adv()
      const s = cs.slice(start, i).join('')
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let ok = true
      // digit run: returns true if at least one digit consumed
      const run = (test) => {
        if (!test(cs[i])) return false
        adv()
        for (;;) {
          if (test(cs[i])) adv()
          else if (cs[i] === '_' && test(cs[i + 1])) { adv(); adv() }
          else break
        }
        return true
      }
      const p = cs[i + 1]
      const base = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d >= '0' && d <= '7' && d.length === 1 }[p] : undefined
      if (base) {
        advN(2)
        ok = run(base)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { adv(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { advN(2); run(isDigit) }
        }
      }
      if (isIdCont(cs[i])) ok = false
      if (!ok) {
        while (isIdCont(cs[i])) adv()
        throw new ScanError(sl, sc, `invalid number ${cs.slice(start, i).join('')}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: cs.slice(start, i).join('') })
      continue
    }
    if (c === '"') {
      adv()
      let val = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line, ec = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') { val += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') val += '\n'
        else if (e === 't') val += '\t'
        else if (e === 'r') val += '\r'
        else if (e === '\\') val += '\\'
        else if (e === '"') val += '"'
        else if (e === '0') val += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          val += String.fromCodePoint(parseInt(cs[i] + cs[i + 1], 16))
          advN(2)
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          val += String.fromCodePoint(v)
          advN(j + 1 - i)
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(val) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      advN(2)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let out
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  if (args[0] === 'tokens') {
    out = tokens.map((t) => `${t.line}:${t.col} ${t.kind} ${t.body}\n`).join('')
  } else {
    out = KINDS.map((k) => `${k} ${tokens.filter((t) => t.kind === k).length}\n`).join('') + `total ${tokens.length}\n`
  }
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
