  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

function analyze(g) {
  const { costs, names, dl } = g
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const calc = (u) => {
    if (finish.has(u)) return
    let s = 0n
    let d = 0
    for (const v of dl.get(u)) {
      calc(v)
      if (finish.get(v) > s) s = finish.get(v)
      if (depth.get(v) + 1 > d) d = depth.get(v) + 1
    }
    start.set(u, s)
    finish.set(u, s + costs.get(u))
    depth.set(u, d)
  }
  for (const k of names) calc(k)
  let total = 0n
  for (const k of names) if (finish.get(k) > total) total = finish.get(k)
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const { costs, names, dl } = g
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of dl.get(k)) rev.get(v).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const p of rev.get(u)) if (pr(p) > m) m = pr(p)
    prio.set(u, m + costs.get(u))
    return prio.get(u)
  }
  for (const k of names) pr(k)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const freeAt = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  let left = names.length
  let t = 0n
  let makespan = 0n
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((k) => !fin.has(k) && dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t))
      if (task === undefined) break
      const f = t + costs.get(task)
      fin.set(task, f)
      freeAt[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      left--
    }
    if (left === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of fin.values()) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  const out = ran.map((r, i) => `worker ${i}:` + r.map((x) => ' ' + x).join(''))
  out.push(`makespan ${makespan}`)
  return out
}

function main() {
  const a = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers
  if (a.length === 1 && (a[0] === 'waves' || a[0] === 'explain')) {
    // ok
  } else if (a.length === 2 && a[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(a[1])
  } else throw new Fail(usage)
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {}
  const g = parse(text)
  checkCycle(g)
  const out = []
  if (a[0] === 'pack') out.push(...pack(g, workers))
  else {
    const r = analyze(g)
    if (a[0] === 'waves') {
      const waves = []
      for (const k of g.names) (waves[r.depth.get(k)] ??= []).push(k)
      waves.forEach((ws, i) => out.push(`wave ${i}: ${ws.join(' ')}`))
    } else {
      for (const k of g.names) out.push(`${k} start=${r.start.get(k)} finish=${r.finish.get(k)} depth=${r.depth.get(k)}`)
    }
    out.push(`total ${r.total}`)
  }
  process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (e) {
  if (e instanceof Fail) {
    process.stderr.write(e.message + '\n')
    process.exit(e.code)
  }
  throw e
}
"}

