    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '').replace(/^\+/, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; break }
      items.push(this.value(path))
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; break }
      if (this.atEnd()) fail('unterminated array')
      fail('trailing text after a value')
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable(true)
    this.ws()
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
