      if (this.c === '}') { this.i++; return tbl }
      if (this.atEnd()) fail('unterminated inline table')
      fail('trailing text after a value')
    }
  }
}

/** Steps into `node` for walking: a table, or the last table of an array of tables. */
function step(node) {
  if (node.t === 'table') return node
  if (node.t === 'array' && node.aot) return node.items[node.items.length - 1]
  return null
}

function walk(tbl, base, keys, p) {
  let cur = tbl
  for (let k = 0; k < keys.length; k++) {
    p.push(keys[k])
    let ch = cur.m.get(keys[k])
    if (!ch) { ch = newTable(false); cur.m.set(keys[k], ch) }
    const nx = step(ch)
    if (!nx) fail(`${[...base, ...p].join('.')} is not a table`)
    cur = nx
  }
  return cur
}

function assign(tbl, base, keys, v) {
  const p = []
  const cur = walk(tbl, base, keys.slice(0, -1), p)
  const last = keys[keys.length - 1]
  if (cur.m.has(last)) fail(`key ${[...base, ...keys].join('.')} is defined twice`)
  cur.m.set(last, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable(true)
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const ln = new Line(lines[n])
      ln.ws()
      if (ln.c === undefined || ln.c === '#' || ln.c === ';') continue
      if (ln.c === '[') {
        const aot = lines[n][ln.i + 1] === '['
        ln.i += aot ? 2 : 1
        ln.ws()
        const keys = ln.dotted()
        ln.ws()
        for (let r = aot ? 2 : 1; r > 0; r--) {
          if (ln.c === ']') ln.i++
          else if (ln.atEnd()) fail('unterminated table header')
          else fail('trailing text after a table header')
        }
        ln.ws()
        if (!ln.atEnd()) fail('trailing text after a table header')
        const p = []
        const parent = walk(root, [], keys.slice(0, -1), p)
        const last = keys[keys.length - 1]
        const full = keys.join('.')
        const ex = parent.m.get(last)
        if (!aot) {
          if (!ex) { cur = newTable(true); parent.m.set(last, cur) }
          else if (ex.t !== 'table') fail(`${full} is not a table`)
          else if (ex.hdr) fail(`table ${full} is defined twice`)
          else { ex.hdr = true; cur = ex }
        } else {
          if (!ex) {
            const a = { t: 'array', items: [], aot: true }
            parent.m.set(last, a)
            cur = newTable(true)
            a.items.push(cur)
          } else if (ex.t !== 'array' || !ex.aot) fail(`${full} is not an array of tables`)
          else { cur = newTable(true); ex.items.push(cur) }
        }
        curPath = keys
        continue
      }
      const keys = ln.dotted()
      ln.ws()
      if (ln.c !== '=') fail('expected key = value')
      ln.i++
      ln.ws()
      const v = ln.value([...curPath, ...keys])
      ln.ws()
      if (!ln.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
