#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parser.js'

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    if (!n.m.size) return '{}'
    return '{\n' + sorted(n.m).map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'string') return JSON.stringify(n.v)
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  const emit = (p, c) => {
    out.push(`${p} ${c.t}`)
    keys(c, p, out)
  }
  if (n.t === 'table') for (const k of sorted(n.m)) emit(path === null ? k : path + '.' + k, n.m.get(k))
  else if (n.t === 'array') n.items.forEach((c, i) => emit(`${path}[${i}]`, c))
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const doc = parse(readFileSync(0, 'utf8'))
  let out
  if (mode === 'json') out = toJson(doc, 0) + '\n'
  else {
    const lines = []
    keys(doc, null, lines)
    out = lines.map((l) => l + '\n').join('')
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
