        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
    t.fragment = ref.fragment
  }
  return reparse(t)
}

function reparse(t) {
  return parse(serialize(t))
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    throw new Fail('error: usage: cli.js normalize|resolve')
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((line, idx) => {
    const n = idx + 1
    if (mode === 'normalize') {
      const r = parse(line)
      checkPercent(r, n)
      out.push(normalize(r))
      return
    }
    const sp = line.indexOf(' ')
    if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
    const base = parse(line.slice(0, sp))
    if (base.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
    const ref = parse(line.slice(sp + 1))
    checkPercent(base, n)
    checkPercent(ref, n)
    out.push(normalize(resolve(base, ref)))
  })
  process.stdout.write(out.map((l) => l + '\n').join(''))
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
