import { GraphError } from './graph.js'

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

/** Topologically analyses the graph; throws a cycle GraphError when needed. */
export function analyze({ costs, deps }) {
  const names = [...costs.keys()].sort(cmp)
  const sortedDeps = new Map(names.map((n) => [n, [...(deps.get(n) ?? [])].sort(cmp)]))
  const state = new Map()
  const stack = []
  const order = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of sortedDeps.get(n)) {
      const s = state.get(d)
      if (s === 1) {
        const cycle = stack.slice(stack.indexOf(d)).concat(d)
        throw new GraphError(`error: cycle: ${cycle.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(n, 2)
    order.push(n)
  }
  for (const n of names) if (!state.get(n)) visit(n)

  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0n
  for (const n of order) {
    let s = 0n
    let d = 0
    for (const x of sortedDeps.get(n)) {
      if (finish.get(x) > s) s = finish.get(x)
      d = Math.max(d, depth.get(x) + 1)
    }
    start.set(n, s)
    finish.set(n, s + costs.get(n))
    depth.set(n, d)
    if (finish.get(n) > total) total = finish.get(n)
  }
  // priority: longest chain starting at each task
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const x of sortedDeps.get(n)) dependents.get(x).push(n)
  const prio = new Map()
  for (const n of [...order].reverse()) {
    let best = 0n
    for (const m of dependents.get(n)) if (prio.get(m) > best) best = prio.get(m)
    prio.set(n, costs.get(n) + best)
  }
  return { names, sortedDeps, start, finish, depth, total, prio }
}

export function pack({ costs }, info, workers) {
  const { names, sortedDeps, prio } = info
  const lanes = Array.from({ length: workers }, () => [])
  const freeAt = new Array(workers).fill(0n)
  const done = new Map()
  const pending = new Set(names)
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const n of pending) {
        if (!sortedDeps.get(n).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick) || (prio.get(n) === prio.get(pick) && n < pick)) pick = n
      }
      if (pick === null) break
      const f = t + costs.get(pick)
      pending.delete(pick)
      done.set(pick, f)
      freeAt[w] = f
      lanes[w].push({ name: pick, start: t, finish: f })
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return { lanes, makespan }
}
