const NAME = /^[A-Za-z0-9_-]+$/

function fail(msg) {
  const e = new Error(msg)
  e.isElectionError = true
  return e
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) throw fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = [...seen]
    } else if (word === 'ballot') {
      if (candidates === null) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) throw fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) throw fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      throw fail(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw fail('error: no candidates')
  return { candidates, ballots }
}

