    if (active === 0n) break
    const top = listed.find((c) => votes.get(c) * 2n > active)
    if (top !== undefined) {
      winner = top
      break
    }
    let tied = [...continuing]
    let min = tied.reduce((m, c) => (votes.get(c) < m ? votes.get(c) : m), votes.get(tied[0]))
    tied = tied.filter((c) => votes.get(c) === min)
