const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(text)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') throw new Fail(`unknown directive ${d}`)
      if (d !== 'event' && lastTick !== null) throw new Fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = int('capacity', f[2], 1)
        const refill = int('refill', f[3], 0)
        const per = int('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per })
